<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { api } from '@/app/runtime';
import { useAsync } from '@/composables/useAsync';
import type { ExhibitionDetail } from '@/api/types';
import { t } from '@/i18n';
const route = useRoute(); const router = useRouter(); const query = useAsync<ExhibitionDetail>(); const answers = reactive<Record<string, string | string[]>>({}); const error = ref(''); const busy = ref(false); const detail = computed(() => query.data.value); const fields = computed(() => detail.value?.fields ?? []);
onMounted(() => query.run(() => api.exhibitions.get(String(route.params.id))));
async function submit() { error.value = ''; busy.value = true; try { for (const field of fields.value) { const value = answers[String(field.id || field.title)]; if (field.required && (!value || (Array.isArray(value) && value.length === 0))) throw new Error(`请填写「${field.title}」`); } const text = fields.value.map((field) => { const value = answers[String(field.id || field.title)]; return `${field.title}：${Array.isArray(value) ? value.join('、') : value || t('s_15h5nhd')}`; }).join('\n'); await api.registrations.submit({ exhibitionId: String(route.params.id), answers: text }); await router.replace('/my-registrations'); } catch (reason) { error.value = reason instanceof Error ? reason.message : String(reason); } finally { busy.value = false; } }
</script>
<template><section class="page"><button class="text-action" @click="router.back()">{{ t('s_omytgn') }}</button><h1>{{ t('s_gluzjf') }}</h1><div v-if="query.loading" class="state">{{ t('s_zw67ah') }}</div><form v-else-if="detail?.exhibition" class="card form" @submit.prevent="submit"><p>{{ detail.exhibition.title }}</p><label v-for="field in fields" :key="String(field.id || field.title)">{{ field.title }}<select v-if="field.type === '单选'" v-model="answers[String(field.id || field.title)]" :required="field.required"><option value="">{{ t('s_390cng') }}</option><option v-for="option in field.options || []" :key="option" :value="option">{{ option }}</option></select><select v-else-if="field.type === '多选'" v-model="answers[String(field.id || field.title)]" multiple :required="field.required"><option v-for="option in field.options || []" :key="option" :value="option">{{ option }}</option></select><input v-else v-model="answers[String(field.id || field.title)]" :required="field.required"></label><p v-if="error" class="error" role="alert">{{ error }}</p><button class="cta" :disabled="busy">{{ t('s_1umrk9v') }}</button></form><p v-else class="state">{{ t('s_1sdwe6p') }}</p></section></template>
